import {loadAnnouncementsPage} from './announcements.js';
import {state,api,permitted} from './api.js';
import {esc,icon,avatar,badge,formatDate,formatTime,empty,button,number,options,localToday,labels} from './ui.js';
export const pageTitles={announcements:'Informasi Internal',dashboard:'Dashboard SDM',employees:'Data Pegawai',organization:'Struktur Organisasi',imports:'Tinjau Impor Pegawai',documents:'Regulasi & SOP',training:'Pelatihan & Standar Layanan',coaching:'Coaching',security:'Dashboard Keamanan',roster:'Jadwal & Penugasan','roster-settings':'Pengaturan Jadwal',logbook:'Logbook & Patroli',incidents:'Laporan Kejadian',sop:'SOP Keamanan',accounts:'Akun Pengguna',roles:'Role & Izin',audit:'Riwayat Aktivitas'};
export const configNames={posts:'Wilayah & pos',groups:'Kelompok',members:'Anggota kelompok',shifts:'Shift',eligibility:'Kelayakan pos',rules:'Aturan kerja',patterns:'Pola rotasi',bindings:'Anchor & fase',requirements:'Kebutuhan rutin',overrides:'Penyesuaian sementara',unavailability:'Ketidaktersediaan'};
const rowAction=(type,id)=>`<button class="icon-button" data-action="detail" data-type="${type}" data-id="${esc(id)}" aria-label="Lihat detail">${icon('chevron')}</button>`;
export const heading=(title,description,actions='')=>`<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`;
const table=(headers,rows,emptyText='Belum ada catatan')=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty(emptyText);
const pagination=count=>`<div class="table-footer"><span>${count?`${(state.page-1)*20+1}–${Math.min(state.page*20,count)} dari ${count}`:'0 catatan'}</span><div class="actions"><button class="chip" data-action="prev-page" ${state.page<=1?'disabled':''}>Sebelumnya</button><button class="chip" data-action="next-page" ${state.page*20>=count?'disabled':''}>Berikutnya</button></div></div>`;
export const footer=()=>`<footer class="page-footer"><span>© ${new Date().getFullYear()} Badan Pengelola Besakih</span><span>${icon('shield')}Portal internal · Waktu operasional WITA</span></footer>`;
const card=(title,sub,body,link='')=>`<section class="card"><header class="card-header"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${link}</header>${body}</section>`;
const more=(route)=>`<a class="button text" href="#${route}">Lihat semua ${icon('arrow')}</a>`;
const stat=(name,value,note,ico)=>`<div class="stat-card"><div class="stat-top"><span>${esc(name)}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${number(value)}</div><div class="stat-bottom">${icon('check')}<span>${esc(note)}</span></div></div>`;
const dateSquare=d=>`<div class="date-square"><span>${esc(formatDate(d,{month:'short'}))}</span><strong>${esc(formatDate(d,{day:'2-digit'}))}</strong></div>`;
const person=(name,sub,i=0)=>`<div class="table-person">${avatar(name,i)}<div><strong>${esc(name)}</strong><small>${esc(sub)}</small></div></div>`;
export async function loadPage(route) {
  if(route==='announcements')return loadAnnouncementsPage();
  state.route=route;state.page=1;state.filter='';state.unit='';state.category='';
  if(['dashboard','security'].includes(route)){state.date=state.date||localToday();state.dashboard=await api(`dashboard?module=${route==='security'?'security':'hr'}&as_of=${state.date}`);return dashboardPage(route==='security');}
  if(route==='employees'){const [rows,lookups]=await Promise.all([api('employees'),api('lookups?purpose=employees')]);state.items=rows.items;state.lookups=lookups;return employeesPage();}
  if(route==='organization'){const [units,positions]=await Promise.all([api('units'),api('positions')]);state.items=units.items;state.positions=positions.items;return organizationPage();}
  if(route==='imports'){const [rows,lookups]=await Promise.all([api('imports'),api('lookups?purpose=employees')]);state.items=rows.items;state.lookups=lookups;return importsPage();}
  if(['documents','sop'].includes(route)){state.items=(await api('documents')).items;if(route==='sop')state.items=state.items.filter(d=>d.category==='SOP_SECURITY');return documentsPage(route==='sop');}
  if(route==='training'){state.items=(await api('training')).items;return trainingPage();}
  if(route==='coaching'){state.items=(await api('coaching')).items;return coachingPage();}
  if(route==='roster'){state.periods=(await api('periods')).items;state.periodId=state.periods.some(p=>p.id===state.periodId)?state.periodId:state.periods[0]?.id;return rosterPage();}
  if(route==='roster-settings'){state.lookups=await api('lookups?purpose=roster');state.items=(await api(`config/${state.configKey}`)).items;return configPage();}
  if(['logbook','incidents'].includes(route)){state.items=(await api(route)).items;return route==='logbook'?logbookPage():incidentsPage();}
  if(route==='accounts'){state.items=(await api('users')).items;return accountsPage();}
  if(route==='roles'){const data=await api('roles');state.items=data.items;state.allPermissions=data.permissions;state.settings=permitted('admin.roles.manage')?await api('settings'):{};return rolesPage();}
  if(route==='audit'){state.items=(await api('audit')).items;return auditPage();}
  return empty('Halaman tidak ditemukan','Pilih salah satu menu pada navigasi.');
}
export function dashboardPage(security=false) {
  const d=state.dashboard,name=state.me?.user.username==='admin.demo'?'Admin':state.me?.name==='admin'?'Admin':(state.me?.name||'').split(' ').slice(0,2).join(' ');
  const dateControl=`<div class="overview-date">${icon('calendar')}<span>Ringkasan per</span><input type="date" aria-label="Tanggal ringkasan" id="dashboard-date" value="${esc(state.date)}"></div>`;
  const hero=`<section class="hero"><div class="hero-content"><div class="eyebrow">${security?'Operasional keamanan':'Sumber daya manusia'}</div><h1>${security?'Kawasan terjaga, layanan terarah.':`Selamat datang, ${esc(name)}.`}</h1><p>${security?'Pantau penugasan, kegiatan patroli, dan tindak lanjut kejadian di satu tempat.':'Kelola pegawai dan dukung pertumbuhan tim untuk pelayanan terbaik di kawasan suci Besakih.'}</p>${security?(permitted('security.logbook.create')?button('Catat kegiatan','new-logbook','plus'):button('Lihat jadwal','go-roster','calendar')):(permitted('hr.employees.create')?button('Tambah pegawai','new-employee'):button('Lihat pegawai','go-employees','people'))}</div><img class="hero-art" src="/app/assets/temple.svg" alt="" aria-hidden="true"></section>`;
  if(security) return `${heading('Dashboard Keamanan','Gambaran operasional kawasan hari ini.',dateControl)}${hero}<div class="stats-grid">${stat('Petugas terjadwal',d.scheduled,'Berdasarkan jadwal terbit','people')}${stat('Kekurangan petugas',d.gap_count,'Slot pada tanggal acuan','calendar')}${stat('Patroli tercatat',d.patrols,'Catatan kegiatan hari ini','shield')}${stat('Kejadian terbuka',d.open_incidents,'Memerlukan tindak lanjut','incident')}</div><div class="grid-two">${card('Penugasan hari ini','Jadwal terbit merupakan rencana penugasan.',d.assignments.length?`<div class="record-list">${d.assignments.slice(0,5).map((a,i)=>`<div class="record-row">${avatar(a.display.employee_name,i)}<div class="record-info"><strong>${esc(a.display.employee_name)}</strong><p>${esc(a.display.post_name)} · ${esc(a.display.shift_name)} · ${formatTime(a.starts_at)}–${formatTime(a.ends_at)}</p></div>${badge('PUBLISHED','Terjadwal')}</div>`).join('')}</div>`:empty('Belum ada jadwal terbit','Susun dan terbitkan jadwal untuk tanggal ini.'),more('roster'))}${card('Kejadian perlu ditangani','Laporan yang belum diselesaikan.',d.incidents.length?`<div class="record-list">${d.incidents.map(i=>`<button class="record-row" data-action="detail" data-type="incidents" data-id="${i.id}"><span class="stat-icon">${icon('incident')}</span><div class="record-info"><strong>${esc(i.incident_type)}</strong><p>${esc(i.post_name||(i.latitude!=null?`${Number(i.latitude).toFixed(5)}, ${Number(i.longitude).toFixed(5)}`:'Lokasi perangkat'))} · ${esc(i.incident_no)}</p></div>${badge(i.status)}</button>`).join('')}</div>`:empty('Tidak ada kejadian terbuka','Seluruh laporan dalam cakupan Anda sudah ditindaklanjuti.'),more('incidents'))}</div>${card('Catatan lapangan terbaru','Kegiatan yang telah dicatat oleh petugas.',d.logs.length?`<div class="record-list">${d.logs.map(l=>`<button class="record-row" data-action="detail" data-type="logbook" data-id="${l.id}"><span class="stat-icon">${icon('log')}</span><div class="record-info"><strong>${esc(l.activity_type)} · ${esc(l.post_name||(l.latitude!=null?`${Number(l.latitude).toFixed(5)}, ${Number(l.longitude).toFixed(5)}`:'—'))}</strong><p>${esc(l.employee_name)} · ${formatDate(l.occurred_at)} ${formatTime(l.occurred_at)}</p></div>${icon('chevron')}</button>`).join('')}</div>`:empty('Belum ada kegiatan tercatat'),more('logbook'))}${footer()}`;
  const unitBars=d.units.slice(0,5).map(u=>`<div><div class="bar-heading"><span>${esc(u.name)}</span><strong>${number(u.count)}</strong></div><progress max="${Math.max(1,...d.units.map(u=>u.count))}" value="${u.count}" aria-label="${esc(u.name)}: ${u.count} pegawai"></progress></div>`).join('');
  const chart=`<div class="card-body"><div class="status-chart"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="Komposisi status ${d.total} pegawai"><circle cx="60" cy="60" r="48"/>${[...d.statuses,{name:"Nonaktif",count:d.inactive}].map((s,i,arr)=>`<circle class="donut-segment tone-${Math.min(i,2)}" cx="60" cy="60" r="48" stroke-dasharray="${d.total?301.59*s.count/d.total:0} 301.59" stroke-dashoffset="${d.total?-301.59*arr.slice(0,i).reduce((sum,x)=>sum+x.count,0)/d.total:0}"/>`).join('')}</svg><div class="donut-label"><strong>${number(d.total)}</strong><span>Total pegawai</span></div></div><div class="legend">${d.statuses.length?d.statuses.slice(0,4).map((s,i)=>`<div class="legend-row"><span class="dot dot-${Math.min(i,2)}"></span><span>${esc(s.name)}</span><strong>${s.count}</strong></div>`).join(''):'<span class="muted text-small">Belum ada pegawai</span>'}<div class="legend-row"><span class="dot dot-2"></span><span>Nonaktif</span><strong>${d.inactive}</strong></div></div></div><p class="chart-caption">Jenis kepegawaian berdasarkan data yang tercatat.</p></div>`;
  return `${heading('Dashboard','Gambaran tim dan aktivitas SDM Anda.',dateControl)}${hero}${d.pending_import?`<div class="notice">${icon('upload')}<div><strong>${d.pending_import} calon data pegawai siap ditinjau.</strong> Lengkapi nomor pegawai, tanggal mulai kerja, dan penempatannya. <a href="#imports">Tinjau data impor</a></div></div>`:''}<div class="stats-grid">${stat('Pegawai aktif',d.active,`${d.total} pegawai tercatat`,'people')}${stat('Unit organisasi',d.units.length,'Dengan penempatan aktif','building')}${stat('Pelatihan mendatang',d.training_count,'Agenda yang direncanakan','training')}${d.can_coaching?stat('Tindak lanjut coaching',d.open_actions,'Tindakan belum selesai','coaching'):stat('Dokumen berlaku',d.document_count,'Versi aktif tersedia','document')}</div><div class="grid-two">${card('Sebaran pegawai','Jumlah pegawai aktif berdasarkan penempatan utama.',`<div class="card-body">${unitBars?`<div class="chart-bars">${unitBars}</div><p class="chart-caption">${d.units.length>5?'Menampilkan lima unit dengan pegawai terbanyak.':'Satu pegawai dihitung satu kali dalam unit utamanya.'}</p>`:empty('Belum ada penempatan pegawai')}</div>`,permitted('hr.employees.read')?more('employees'):'')}${card('Status kepegawaian','Komposisi tim BP Besakih.',chart)}</div><div class="grid-two grid-equal">${card('Pelatihan mendatang','Persiapkan pengembangan tim berikutnya.',d.training.length?`<div class="record-list">${d.training.map(t=>`<button class="record-row" data-action="detail" data-type="training" data-id="${t.id}">${dateSquare(t.starts_at)}<div class="record-info"><strong>${esc(t.title)}</strong><p>${formatTime(t.starts_at)} WITA · ${esc(t.location||'Lokasi belum diisi')}</p></div>${icon('chevron')}</button>`).join('')}</div>`:empty('Belum ada agenda pelatihan','Pelatihan yang direncanakan akan tampil di sini.','training'),permitted('hr.training.read')?more('training'):'')}${d.can_coaching?card('Tindak lanjut coaching','Perkembangan yang memerlukan perhatian.',d.coaching.length?`<div class="record-list">${d.coaching.map((s,i)=>`<button class="record-row" data-action="detail" data-type="coaching" data-id="${s.id}">${avatar(s.employee_name,i)}<div class="record-info"><strong>${esc(s.topic)}</strong><p>${esc(s.employee_name)} · ${s.open_actions} tindak lanjut terbuka</p></div>${icon('chevron')}</button>`).join('')}</div>`:empty('Belum ada tindak lanjut terbuka','Riwayat coaching hanya terlihat oleh pihak yang berhak.','coaching'),more('coaching')):card('Dokumen terbaru','SOP dan regulasi yang sedang berlaku.',d.documents.length?`<div class="record-list">${d.documents.map(doc=>`<button class="record-row" data-action="detail" data-type="documents" data-id="${doc.id}"><span class="stat-icon">${icon('document')}</span><div class="record-info"><strong>${esc(doc.title)}</strong><p>Versi ${esc(doc.version_label)} · ${formatDate(doc.effective_on)}</p></div>${icon('chevron')}</button>`).join('')}</div>`:empty('Belum ada dokumen berlaku'),more('documents'))}</div>${footer()}`;
}
const employeeTabs=active=>`<nav class="tabs" aria-label="Data pegawai">${[['employees','Daftar pegawai'],['organization','Struktur organisasi'],...(permitted('hr.employees.create')?[['imports','Tinjau impor']]:[])].map(([r,label])=>`<a class="tab ${r===active?'active':''}" href="#${r}">${label}</a>`).join('')}</nav>`;
export function employeesPage(){return `${heading('Data Pegawai & Organisasi','Satu sumber data untuk seluruh tim BP Besakih.',(permitted('hr.employees.export')?button('Ekspor','export-employees','download','outlined'):'')+(permitted('hr.employees.create')?button('Tambah pegawai','new-employee'):''))}${employeeTabs('employees')}<section class="card"><div class="toolbar"><label class="search-field">${icon('search')}<input id="list-search" placeholder="Cari nama atau nomor pegawai…" aria-label="Cari pegawai"></label><select id="unit-filter" aria-label="Filter unit">${options(state.lookups.units,'id','name','','Semua unit')}</select><span class="chip">${state.items.length} pegawai</span></div><div id="data-list">${employeeRows()}</div></section>${footer()}`;}
export function employeeRows(){const rows=state.items.filter(e=>(!state.filter||`${e.full_name} ${e.employee_no}`.toLowerCase().includes(state.filter))&&(!state.unit||e.org_unit_id===state.unit));const page=rows.slice((state.page-1)*15,state.page*15);return table(['Pegawai','Unit & posisi','Status pegawai','Mulai bekerja','Status',''],page.map((e,i)=>`<tr><td>${person(e.full_name,e.employee_no,i)}</td><td><div>${esc(e.unit_name||'Belum ditempatkan')}</div><small class="muted">${esc(e.position_name||'—')}</small></td><td>${esc(e.employment_status)}</td><td class="nowrap">${formatDate(e.joined_on)}</td><td>${badge(e.is_active?'ACTIVE':'INACTIVE')}</td><td>${rowAction('employees',e.id)}</td></tr>`),'Pegawai tidak ditemukan')+`<div class="table-footer"><span>${rows.length?`${(state.page-1)*15+1}–${Math.min(state.page*15,rows.length)} dari ${rows.length}`:'0 pegawai'}</span><div class="actions"><button class="chip" data-action="prev-page" ${state.page<=1?'disabled':''}>Sebelumnya</button><button class="chip" data-action="next-page" ${state.page*15>=rows.length?'disabled':''}>Berikutnya</button></div></div>`;}
export function organizationPage(){const depth=u=>{let n=0,p=u.parent_id,seen=new Set();while(p&&!seen.has(p)){seen.add(p);n++;p=state.items.find(i=>i.id===p)?.parent_id;}return Math.min(n,3);};return `${heading('Data Pegawai & Organisasi','Struktur fungsi dan posisi BP Besakih.',permitted('hr.organization.manage')?button('Tambah unit','new-unit')+button('Tambah posisi','new-position','plus','outlined'):'')}${employeeTabs('organization')}<div class="org-list">${state.items.map(u=>`<div class="card org-unit org-indent-${depth(u)}"><span class="stat-icon">${icon('building')}</span><div class="record-info"><strong>${esc(u.name)}</strong><p>${esc(u.code)} · ${state.positions.filter(p=>p.org_unit_id===u.id).length} posisi · ${u.is_active?'Aktif':'Nonaktif'}</p></div><div class="actions">${permitted('hr.organization.manage')?`<button class="icon-button" data-action="edit-unit" data-id="${u.id}" aria-label="Ubah unit">${icon('edit')}</button>`:''}</div></div>`).join('')||empty('Belum ada unit organisasi')}</div><div class="card detail-section"><header class="card-header"><h2>Daftar posisi</h2></header><div class="card-body">${table(['Posisi','Unit','Kode',''],state.positions.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(state.items.find(u=>u.id===p.org_unit_id)?.name)}</td><td>${esc(p.code)}</td><td>${permitted('hr.organization.manage')?`<button class="icon-button" data-action="edit-position" data-id="${p.id}" aria-label="Ubah posisi">${icon('edit')}</button>`:''}</td></tr>`))}</div></div>${footer()}`;}
export function importsPage(){return `${heading('Tinjau Impor Pegawai','Validasi data dari bagan organisasi sebelum menjadi profil pegawai.')}${employeeTabs('imports')}<div class="notice warning">${icon('document')}<p>Bagan tidak memuat nomor pegawai, tanggal mulai kerja, atau status kepegawaian resmi. Isi data tersebut dari catatan yang sudah diverifikasi. Nama yang muncul di beberapa posisi tetap menjadi satu profil pegawai.</p></div><section class="card"><div class="toolbar"><label class="search-field">${icon('search')}<input id="list-search" placeholder="Cari calon data pegawai…" aria-label="Cari data impor"></label><span class="chip">${state.items.length} belum ditinjau</span></div><div id="data-list">${importRows()}</div></section>${footer()}`;}
export function importRows(){const rows=state.items.filter(c=>`${c.full_name} ${c.position_name}`.toLowerCase().includes(state.filter));return table(['Nama dari bagan','Posisi sumber','Referensi',''],rows.slice((state.page-1)*20,state.page*20).map((c,i)=>`<tr><td>${person(c.full_name,'Belum menjadi data aktif',i)}</td><td><div>${esc(c.position_name)}</div><small class="muted">${esc(c.org_path)}</small></td><td class="monospace">${esc(c.source_cell)}</td><td>${button('Tinjau','review-import','check','tonal',`data-id="${c.id}"`)}</td></tr>`),'Tidak ada calon data yang ditampilkan')+pagination(rows.length);}
export function documentsPage(sop=false){const manage=permitted('hr.documents.manage');return `${heading(sop?'SOP Keamanan':'Regulasi & SOP',sop?'Panduan keamanan dari pusat dokumen yang sama.':'Dokumen terpusat dengan versi dan tanggal berlaku yang jelas.',manage?button('Tambah dokumen','new-document'):'')}<div class="chips">${(sop?['','SOP_SECURITY']:['','REGULATION','SOP','SOP_SECURITY','SERVICE_STANDARD']).map(c=>`<button class="chip ${state.category===c?'active':''}" data-action="category" data-value="${c}">${c?labels[c]:'Semua dokumen'}</button>`).join('')}</div><div id="data-list">${documentRows()}</div>${footer()}`;}
export function documentRows(){const items=state.items.filter(d=>!state.category||d.category===state.category);return items.length?`<div class="document-grid">${items.map(d=>`<button class="card document-card" data-action="detail" data-type="documents" data-id="${d.id}"><span class="stat-icon">${icon('document')}</span><span class="eyebrow">${esc(labels[d.category])}</span><h3>${esc(d.title)}</h3><p>${esc(d.document_code)} · ${esc(d.unit_name)}</p><div class="document-card-foot">${d.active_version?badge('ACTIVE',`Versi ${d.active_version}`):badge('DRAFT','Belum berlaku')}<span class="muted">${d.effective_on?formatDate(d.effective_on):'Menunggu aktivasi'}</span></div></button>`).join('')}</div>`:empty('Belum ada dokumen','Tambahkan dokumen, unggah versi, lalu aktifkan ketika tanggal berlakunya tiba.','document');}
export function trainingPage(){return `${heading('Pelatihan & Standar Layanan','Rencanakan pengembangan, kelola peserta, dan catat kehadiran.',permitted('hr.training.manage')?button('Buat pelatihan','new-training'):'')}<div class="notice">${icon('document')}<span>Standar layanan menggunakan versi resmi dari pusat dokumen. <a href="#documents">Buka Regulasi & SOP</a></span></div><div class="document-grid">${state.items.map(t=>`<button class="card document-card" data-action="detail" data-type="training" data-id="${t.id}">${dateSquare(t.starts_at)}${badge(t.status)}<h3>${esc(t.title)}</h3><p>${esc(t.topic)}</p><p>${icon('location')} ${esc(t.location||'Lokasi belum ditentukan')}</p><div class="document-card-foot"><span>${formatDate(t.starts_at)} · ${formatTime(t.starts_at)} WITA</span><span>${t.participant_count} peserta</span></div></button>`).join('')}</div>${state.items.length?'':empty('Belum ada pelatihan','Buat agenda pengembangan untuk mulai mencatat pelatihan tim.','training')}${footer()}`;}
export function coachingPage(){return `${heading('Evaluasi & Penilaian','Pendampingan pegawai dan tindak lanjut pengembangan.',permitted('hr.coaching.manage')||permitted('hr.coaching.create')?button('Catat coaching','new-coaching'):'')}<div class="notice">${icon('lock')}<p>Isi coaching hanya dapat dibaca pihak yang terlibat atau pengelola coaching yang ditunjuk. Penanggung jawab tindak lanjut tidak otomatis mendapat akses ke seluruh sesi.</p></div><section class="card">${table(['Pegawai & pembimbing','Topik coaching','Tanggal sesi','Tindak lanjut',''],state.items.map((s,i)=>`<tr><td>${person(s.employee_name,`Pembimbing: ${s.coach_name}`,i)}</td><td>${esc(s.topic)}</td><td>${formatDate(s.held_at)}</td><td>${badge(s.open_actions?'IN_PROGRESS':'DONE',`${s.open_actions} terbuka`)}</td><td>${rowAction('coaching',s.id)}</td></tr>`),'Belum ada sesi coaching dalam cakupan Anda')}</section>${footer()}`;}
export async function rosterPage(){
  const period=state.periods.find(p=>p.id===state.periodId);if(period){state.revisionId=period.revisions.some(r=>r.id===state.revisionId)?state.revisionId:period.revisions[0]?.id;state.revision=state.revisionId?await api(`revisions/${state.revisionId}`):null;}else state.revision=null;
  const rev=state.revision,draft=rev?.status==='DRAFT';
  return `${heading('Jadwal & Penugasan','Rotasi rutin, penyesuaian sementara, dan riwayat revisi.',(permitted('security.config.read')?button('Pengaturan','go-config','settings','outlined'):'')+(permitted('security.roster.generate')?button('Buat periode','new-period'):''))}<div class="roster-periods">${state.periods.map(p=>`<button class="card period-card ${p.id===state.periodId?'selected':''}" data-action="select-period" data-id="${p.id}"><strong>${esc(p.name)}</strong><p>${formatDate(p.starts_on)} – ${formatDate(p.ends_on)}</p><small>${p.revisions.length} revisi tersedia</small></button>`).join('')}</div>${!period?empty('Belum ada periode jadwal','Lengkapi pengaturan shift, kebutuhan, aturan kerja, dan rotasi, lalu buat periode pertama.','calendar'):`<div class="revision-toolbar"><div class="actions">${period.revisions.length?`<select id="revision-selector" aria-label="Pilih revisi">${period.revisions.map(r=>`<option value="${r.id}" ${r.id===state.revisionId?'selected':''}>Revisi ${r.revision_no} · ${labels[r.status]}</option>`).join('')}</select>`:'<span class="muted">Belum ada draf</span>'}${rev?badge(rev.status):''}</div><div class="actions">${permitted('security.roster.generate')?button('Draf revisi baru','new-revision','plus','outlined'):''}${draft&&permitted('security.roster.generate')?button('Susun otomatis','generate','spark'):''}</div></div>${rev?`${draft?`<div class="notice ${rev.report?.errors?.length?'error':''}">${icon(rev.report?.errors?.length?'incident':'calendar')}<div><strong>${rev.assignments.length} penugasan · ${rev.report?.gap_count||0} slot kurang · ${rev.report?.errors?.length||0} konflik</strong><p>Draf belum terlihat oleh petugas. ${rev.report?.errors?.slice(0,3).map(e=>esc(e.message)).join(' ')||'Validasi ulang sebelum menerbitkan jadwal.'}</p></div></div><div class="actions detail-section">${permitted('security.roster.edit')?button('Tambah penugasan','manual-assignment','plus','outlined')+button('Validasi ulang','validate-roster','check','outlined'):''}${permitted('security.roster.acknowledge')&&rev.gaps.length?button('Akui kekurangan','acknowledge-gaps','incident','outlined'):''}${permitted('security.roster.publish')?button('Terbitkan jadwal','publish-roster','upload','primary'):''}</div>`:`<div class="notice">${icon('shield')}<p>Jadwal ${labels[rev.status].toLowerCase()} · ${rev.published_at?formatDate(rev.published_at):''}. Perubahan dilakukan melalui draf revisi baru.</p></div>`}${rev.gaps.length?`<section class="card detail-section"><header class="card-header"><h2>Kekurangan penjagaan</h2></header><div class="card-body">${table(['Tanggal','Pos','Shift','Kebutuhan','Terisi','Pengakuan'],rev.gaps.map(g=>`<tr><td>${formatDate(g.service_date)}</td><td>${esc(g.post_name)}</td><td>${esc(g.shift_name)}</td><td>${g.required_count}</td><td>${g.assigned_count}</td><td>${badge(g.acknowledged_by?'ACTIVE':'DRAFT',g.acknowledged_by?'Diakui':'Belum diakui')}</td></tr>`))}</div></section>`:''}<section class="card"><div class="toolbar"><strong>Daftar penugasan</strong><span class="chip">${rev.assignments.length} terjadwal</span>${permitted('security.roster.export')?button('Ekspor','export-roster','download','text'):''}</div>${table(['Tanggal','Petugas','Pos & shift','Jam WITA','Sumber',''],rev.assignments.map((a,i)=>`<tr><td class="nowrap">${formatDate(a.service_date)}</td><td>${person(a.display.employee_name,a.display.employee_no,i)}</td><td>${esc(a.display.post_name)}<br><small class="muted">${esc(a.display.shift_name)}</small></td><td class="nowrap">${formatTime(a.starts_at)}–${formatTime(a.ends_at)}${formatDate(a.ends_at)!==formatDate(a.starts_at)?' (+1 hari)':''}</td><td>${badge(a.origin)} ${a.is_locked?icon('lock'):''}</td><td>${draft&&permitted('security.roster.edit')?`<div class="actions"><button class="icon-button" data-action="lock-assignment" data-id="${a.id}" aria-label="${a.is_locked?'Buka kunci':'Kunci'} penugasan">${icon(a.is_locked?'key':'lock')}</button>${!a.is_locked?`<button class="icon-button" data-action="remove-assignment" data-id="${a.id}" aria-label="Hapus penugasan">${icon('trash')}</button>`:''}</div>`:''}</td></tr>`),'Draf belum memiliki penugasan')}</section>`:empty('Buat draf revisi','Pilih aturan kerja yang sudah disepakati untuk menyusun jadwal.')}`}${footer()}`;
}
export function configPage(){const rows=state.items,l=state.lookups;const employee=id=>l.employees?.find(e=>e.id===id)?.full_name||id,post=id=>l.posts?.find(p=>p.id===id)?.name||id,shift=id=>l.shifts?.find(s=>s.id===id)?.name||id;
  const summaries={posts:r=>[r.name,r.code,r.location_notes||'—'],groups:r=>[r.name,r.code,r.is_active?'Aktif':'Nonaktif'],shifts:r=>[r.name,`${r.start_time}–${r.end_time}${r.end_day_offset?' (+1 hari)':''}`,r.code],members:r=>[employee(r.employee_id),l.groups?.find(g=>g.id===r.security_group_id)?.name||r.security_group_id,`${formatDate(r.valid_from)} – ${r.valid_to?formatDate(r.valid_to):'seterusnya'}`],eligibility:r=>[employee(r.employee_id),post(r.post_id),`${formatDate(r.valid_from)} – ${r.valid_to?formatDate(r.valid_to):'seterusnya'}`],unavailability:r=>[employee(r.employee_id),`${formatDate(r.starts_at)} ${formatTime(r.starts_at)} – ${formatDate(r.ends_at)} ${formatTime(r.ends_at)}`,r.reason],rules:r=>[`Versi ${r.version_no}`,`Jeda ${r.min_rest_minutes} menit · ${r.max_consecutive_work_days} hari beruntun`,`${r.max_work_minutes_per_local_day} menit/hari · ${r.max_work_minutes_rolling_7_days} menit/7 hari`],patterns:r=>[r.name,`${r.cycle_length_days} hari · versi ${r.version_no}`,r.steps?.map(s=>s.step_kind==='REST'?'Libur':shift(s.shift_id)).join(' → ')],bindings:r=>[employee(r.employee_id),l.patterns?.find(p=>p.id===r.pattern_version_id)?.name||r.pattern_version_id,`Anchor ${formatDate(r.anchor_date)} · fase ${r.phase_offset_days} · efektif ${formatDate(r.effective_from)}`],requirements:r=>[post(r.post_id),`${shift(r.shift_id)} · hari ${r.weekday_no}`,`${r.required_count} petugas · ${formatDate(r.effective_from)}`],overrides:r=>[post(r.post_id),`${shift(r.shift_id)} · ${r.replacement_required_count} petugas`,`${formatDate(r.starts_on)}–${formatDate(r.ends_on)} · ${r.reason}`]};
  return `${heading('Pengaturan Jadwal','Lengkapi konfigurasi operasional sebelum menyusun jadwal.',button('Kembali','go-roster','arrow','outlined')+(permitted('security.config.manage')?button('Tambah','new-config'):''))}<div class="notice warning">${icon('settings')}<p>Jam shift, batas kerja, jeda istirahat, anchor, dan kebutuhan pos ditentukan oleh pengelola. Nilai demo hanya tersedia pada database demonstrasi. Kebutuhan rutin harus terisi untuk setiap hari, pos, dan shift, termasuk kebutuhan nol.</p></div><div class="config-grid">${Object.entries(configNames).map(([key,name])=>`<button class="chip ${key===state.configKey?'active':''}" data-action="config-tab" data-key="${key}">${esc(name)}</button>`).join('')}</div><section class="card">${table([configNames[state.configKey],'Rincian','Keterangan',''],rows.map(r=>`<tr>${summaries[state.configKey](r).map(v=>`<td>${esc(v)}</td>`).join('')}<td>${permitted('security.config.manage')&&!['rules','patterns','bindings'].includes(state.configKey)?`<button class="icon-button" data-action="edit-config" data-id="${r.id}" aria-label="Ubah pengaturan">${icon('edit')}</button>`:''}</td></tr>`))}</section>${footer()}`;
}
export function logbookPage(){return `${heading('Logbook & Patroli','Catatan kegiatan jaga, temuan, dan patroli lapangan.',permitted('security.logbook.create')?button('Catat kegiatan','new-logbook'):'')}<section class="card"><div class="toolbar"><label class="search-field">${icon('search')}<input id="list-search" placeholder="Cari uraian atau petugas…" aria-label="Cari logbook"></label><span class="chip">${state.items.length} catatan</span></div><div id="data-list">${logbookRows()}</div></section>${footer()}`;}
export function logbookRows(){const rows=state.items.filter(l=>`${l.activity_notes} ${l.employee_name} ${l.post_name}`.toLowerCase().includes(state.filter));return table(['Waktu WITA','Kegiatan & petugas','Lokasi pelaporan','Uraian',''],rows.slice((state.page-1)*20,state.page*20).map(l=>`<tr><td class="nowrap">${formatDate(l.occurred_at)}<br><small class="muted">${formatTime(l.occurred_at)}</small></td><td>${person(l.employee_name,labels[l.activity_type])}</td><td>${esc(l.post_name||(l.latitude!=null?`${Number(l.latitude).toFixed(5)}, ${Number(l.longitude).toFixed(5)}`:'—'))}</td><td>${esc(l.activity_notes.slice(0,90))}${l.activity_notes.length>90?'…':''}</td><td>${rowAction('logbook',l.id)}</td></tr>`))+pagination(rows.length);}
export function incidentsPage(){return `${heading('Laporan Kejadian','Tindak lanjuti laporan dengan penanggung jawab dan riwayat yang jelas.',permitted('security.incidents.create')?button('Laporkan kejadian','new-incident'):'')}<div class="chips">${['','RECORDED','IN_PROGRESS','RESOLVED'].map(s=>`<button class="chip ${state.category===s?'active':''}" data-action="category" data-value="${s}">${s?labels[s]:'Semua laporan'}</button>`).join('')}</div><div id="data-list">${incidentRows()}</div>${footer()}`;}
export function incidentRows(){const rows=state.items.filter(i=>!state.category||i.status===state.category);return `<section class="card">${table(['Laporan','Waktu kejadian','Lokasi','Penanggung jawab','Status',''],rows.slice((state.page-1)*20,state.page*20).map(i=>`<tr><td><strong>${esc(i.incident_type)}</strong><br><small class="muted">${esc(i.incident_no)}</small></td><td class="nowrap">${formatDate(i.occurred_at)}<br><small class="muted">${formatTime(i.occurred_at)} WITA</small></td><td>${esc(i.post_name||(i.latitude!=null?`${Number(i.latitude).toFixed(5)}, ${Number(i.longitude).toFixed(5)}`:'Lokasi perangkat'))}</td><td>${esc(i.responsible_name||'Belum ditetapkan')}</td><td>${badge(i.status)}</td><td>${rowAction('incidents',i.id)}</td></tr>`))}${pagination(rows.length)}</section>`;}
export function accountsPage(){return `${heading('Akun Pengguna','Kelola akun dan cakupan akses tanpa mengubah jabatan organisasi.',permitted('admin.users.manage')?button('Buat akun','new-account'):'')}<section class="card">${table(['Akun','Role & cakupan','Status','Terakhir masuk',''],state.items.map(u=>`<tr><td>${person(u.username,u.must_change_password?'Wajib ganti password':'Password sudah diperbarui')}</td><td>${u.grants.map(g=>`<div>${esc(g.role_name)} <small class="muted">· ${esc(labels[g.scope_kind])}</small></div>`).join('')||'<span class="muted">Belum ada role</span>'}</td><td>${badge(u.status)}</td><td>${u.last_login_at?formatDate(u.last_login_at):'Belum masuk'}</td><td>${rowAction('users',u.id)}</td></tr>`))}</section>${footer()}`;}
export function rolesPage(){return `${heading('Role & Izin','Izin tindakan dan cakupan data dievaluasi pada setiap permintaan.',permitted('admin.roles.manage')?button('Buat role','new-role'):'')}<div class="notice">${icon('lock')}<p>Super Admin tidak otomatis mendapat akses isi coaching atau berkas pegawai. Buat dan berikan role yang sesuai tanggung jawab. Cakupan unit atau pos ditetapkan saat role diberikan kepada akun.</p></div><div class="document-grid">${state.items.map(r=>`<button class="card document-card" data-action="edit-role" data-id="${r.id}"><span class="stat-icon">${icon('key')}</span><h3>${esc(r.name)}</h3><p>${esc(r.description||r.code)}</p><div class="document-card-foot"><span>${r.permissions.length} izin</span>${badge(r.is_active?'ACTIVE':'INACTIVE',r.is_system?'Role sistem':undefined)}</div></button>`).join('')}</div>${permitted('admin.roles.manage')?`<section class="card detail-section"><header class="card-header"><div><h2>Kebijakan publikasi jadwal</h2><p>Kekurangan tetap tidak boleh mengesampingkan pelanggaran penugasan.</p></div></header><div class="card-body"><div class="section-title"><div>${badge(state.settings.allow_gap_publication==='true'?'ACTIVE':'DRAFT',state.settings.allow_gap_publication==='true'?'Kekurangan boleh diakui dengan alasan':'Publikasi dengan kekurangan diblokir')}</div>${button('Ubah kebijakan','change-policy','settings','outlined')}</div></div></section>`:''}${footer()}`;}
export function auditPage(){return `${heading('Riwayat Aktivitas','500 aktivitas terbaru. Riwayat audit tidak dapat diubah.')}<section class="card">${table(['Waktu WITA','Pelaku','Tindakan','Objek','Keterangan'],state.items.map(a=>`<tr><td class="nowrap">${formatDate(a.occurred_at)}<br><small class="muted">${formatTime(a.occurred_at)}</small></td><td>${esc(a.actor_name||'Sistem')}</td><td><span class="chip">${esc(a.action)}</span></td><td>${esc(a.object_type)}<br><small class="monospace muted">${esc(a.object_key.slice(0,12))}</small></td><td>${esc(a.reason||'—')}</td></tr>`))}</section>${footer()}`;}
